-- PROCEDURE `indicators_lib`.`p3`
DROP PROCEDURE IF EXISTS `indicators_lib`.`p3`;
DELIMITER $$
CREATE DEFINER=`root`@`%` PROCEDURE `p3`()
begin 
    DECLARE columnName varchar(255);
	DECLARE cnum int DEFAULT 0;
    DECLARE done INT DEFAULT FALSE;
	
	
    DECLARE my_cursor CURSOR FOR select COLUMN_NAME from information_schema.COLUMNS where table_name = 'lib_index_formula';
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = TRUE;
    	
    open my_cursor;
        xxoo: LOOP
            fetch my_cursor into columnName;					

			
			

			set cnum = (select count(1) from lib_index_formula where columnName !='' and columnName is not null);
			if done then 
                leave xxoo;
			ELSE 		
				
				insert into a_notnull_num values('person_contact_test',columnName,cnum);
			END IF;
			
			
			select columnName;
            select cnum;
						
        end loop xxoo;
    close my_cursor;
end
$$
DELIMITER ;

-- PROCEDURE `indicators_lib`.`p_exe_formula`
DROP PROCEDURE IF EXISTS `indicators_lib`.`p_exe_formula`;
DELIMITER $$
CREATE DEFINER=`root`@`%` PROCEDURE `p_exe_formula`(IN V_DATA_DATE VARCHAR (20))
BEGIN
  DECLARE V_PROC_NAME     VARCHAR(80)   DEFAULT 'INDICATORS_LIB.P_EXE_FORMULA.PRC';
  DECLARE V_START_TIME    CHAR(19)      DEFAULT NOW();
  DECLARE V_STEP_ID       INT           DEFAULT 0;
  DECLARE P_DATA_DATE     VARCHAR(8)	DEFAULT	DATE_FORMAT(V_DATA_DATE,'%Y-%m');
  
  DECLARE done INT DEFAULT 0;
  DECLARE index_id VARCHAR (32);
  DECLARE table_name VARCHAR (200);
  DECLARE deleteSql VARCHAR (2000);
  DECLARE sesin VARCHAR (20000);
  DECLARE insertStr VARCHAR (2000);
  DECLARE whereStr VARCHAR (2000);
  DECLARE sqlText CURSOR FOR
  SELECT
    ID,
    INDEX_CORRE_TABLE,
    EXE_DEL,
    EXE_INSERT,
    EXE_SQL,
    EXE_WHERE
  FROM
    `indicators_lib`.`lib_index_formula`
    ORDER BY IDENTITY_PROPERTY;
  DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = 1;
  
   DECLARE EXIT HANDLER FOR SQLEXCEPTION
   BEGIN
       GET DIAGNOSTICS CONDITION 1 @V_RETURN_CODE = RETURNED_SQLSTATE ,@V_ERROR_MSG = MESSAGE_TEXT;
       CALL ETL.EDW_PROC_ERROR_LOG(P_DATA_DATE,V_START_TIME,NOW(),TABLE_NAME,V_STEP_ID,@V_RETURN_CODE,@V_ERROR_MSG);
   END;
  
  OPEN sqlText;
  WHILE
    done <> 1 DO FETCH sqlText INTO index_id, table_name, deleteSql, insertStr, sesin, whereStr;
    IF done <> 1
    THEN 
    
    SET @LAST_DATE = DATE_SUB(V_DATA_DATE,INTERVAL 1 YEAR);
    SET @DATA_DATE = V_DATA_DATE;
    SET @ID = INDEX_ID;       
    
    SET V_STEP_ID = 1;
    SET @dele_sql = deleteSql;
    PREPARE aaa FROM @dele_sql;
    EXECUTE aaa;
    DEALLOCATE PREPARE aaa; 
    
        CALL ETL.EDW_PROC_TRACE_LOG(P_DATA_DATE,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());  
    
    SET V_STEP_ID = 2;
    SET @insert_sql = CONCAT_WS('', insertStr, sesin, whereStr);
    PREPARE sss FROM @insert_sql;
    EXECUTE sss;
    DEALLOCATE PREPARE sss;
    CALL ETL.EDW_PROC_TRACE_LOG(P_DATA_DATE,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());  
    
    END IF;
  END WHILE;
  CLOSE sqlText;
END
$$
DELIMITER ;

-- PROCEDURE `indicators_lib`.`p_exe_formula_hand`
DROP PROCEDURE IF EXISTS `indicators_lib`.`p_exe_formula_hand`;
DELIMITER $$
CREATE DEFINER=`root`@`%` PROCEDURE `p_exe_formula_hand`(in v_data_date varchar(20), in v_index_id varchar(32))
BEGIN
  DECLARE V_PROC_NAME     VARCHAR(80)   DEFAULT 'INDICATORS_LIB.P_EXE_FORMULA_HAND.PRC';
  DECLARE V_START_TIME    CHAR(19)      DEFAULT NOW();
  DECLARE V_STEP_ID       INT           DEFAULT 0;
  DECLARE P_DATA_DATE     VARCHAR(8)	DEFAULT	DATE_FORMAT(V_DATA_DATE,'%Y-%m');
  DECLARE done INT DEFAULT 0;
  DECLARE index_id VARCHAR (32);
  DECLARE table_name VARCHAR (200);
  declare deleteSql varchar (2000);
  DECLARE sesin VARCHAR (20000);
  DECLARE insertStr VARCHAR (2000);
  DECLARE whereStr VARCHAR (2000);
  DECLARE sqlText CURSOR FOR
  SELECT
    ID,
    INDEX_CORRE_TABLE,
    EXE_DEL,
    EXE_INSERT,
    EXE_SQL,
    EXE_WHERE
  FROM
    `indicators_lib`.`lib_index_formula`
  WHERE
     ID = v_index_id;
  DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = 1;
  
   DECLARE EXIT HANDLER FOR SQLEXCEPTION
   BEGIN
       GET DIAGNOSTICS CONDITION 1 @V_RETURN_CODE = RETURNED_SQLSTATE ,@V_ERROR_MSG = MESSAGE_TEXT;
       CALL ETL.EDW_PROC_ERROR_LOG(P_DATA_DATE,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,@V_RETURN_CODE,@V_ERROR_MSG);
   END;
   
  OPEN sqlText;
  WHILE
    done <> 1 DO FETCH sqlText INTO index_id, table_name, deleteSql, insertStr, sesin, whereStr;
    IF done <> 1
    THEN 
    
    set @LAST_DATE = date_sub(V_DATA_DATE,INTERVAL 1 YEAR);
    set @DATA_DATE = V_DATA_DATE;
    SET @ID = INDEX_ID;    
    
    SET V_STEP_ID = 1;
    SET @dele_sql = deleteSql;
    PREPARE aaa FROM @dele_sql;
    EXECUTE aaa;
    DEALLOCATE PREPARE aaa;
    
        CALL ETL.EDW_PROC_TRACE_LOG(P_DATA_DATE,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());    
    
    SET V_STEP_ID = 2;
    SET @insert_sql = CONCAT_ws('', insertStr, sesin, whereStr);
    PREPARE sss FROM @insert_sql;
    EXECUTE sss;
    DEALLOCATE PREPARE sss;
    
	CALL ETL.EDW_PROC_TRACE_LOG(P_DATA_DATE,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());    
    END IF;
  END WHILE;
  CLOSE sqlText;
	END
$$
DELIMITER ;

-- PROCEDURE `indicators_lib`.`p_exe_formula_history_hand`
DROP PROCEDURE IF EXISTS `indicators_lib`.`p_exe_formula_history_hand`;
DELIMITER $$
CREATE DEFINER=`root`@`localhost` PROCEDURE `p_exe_formula_history_hand`(in v_period_flag varchar(2), 
																																				in v_index_id varchar(32),
																																				out v_out varchar(1000))
BEGIN
  
	
	
  DECLARE V_PROC_NAME     VARCHAR(80)   DEFAULT 'INDICATORS_LIB.P_EXE_FORMULA_HISTORY_HAND.PRC';
  DECLARE V_START_TIME    CHAR(19)      DEFAULT NOW();
  DECLARE V_STEP_ID       INT           DEFAULT 0;
  DECLARE P_DATA_DATE     VARCHAR(8)	DEFAULT	DATE_FORMAT(NOW(),'%Y-%m');
	
	DECLARE V_END_DATE VARCHAR(20);
  
  DECLARE done INT DEFAULT 0;
  DECLARE index_id VARCHAR (32);
  DECLARE table_name VARCHAR (200);
  DECLARE deleteSql varchar (2000);
  DECLARE selectStr text;
  DECLARE insertStr VARCHAR (2000);
  DECLARE whereStr VARCHAR (2000);
  DECLARE buildType VARCHAR (2);
	
	DECLARE updateStr VARCHAR (2000) DEFAULT CONCAT('UPDATE indicators_lib.`lib_index_relation` SET RUN_BATCH_STATUS=@ WHERE INDEX_ID=''', v_index_id,'''');
	
	DECLARE sqlText CURSOR FOR
					SELECT ID,INDEX_CORRE_TABLE,EXE_DEL,EXE_INSERT,EXE_SQL,EXE_WHERE,BUILD_TYPE FROM `indicators_lib`.`lib_index_formula` WHERE ID = v_index_id;
	
	
  DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = 1;
	
	
  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
	   
		 ROLLBACK;
		 
		 GET DIAGNOSTICS CONDITION 1 @V_RETURN_CODE = RETURNED_SQLSTATE ,@V_ERROR_MSG = MESSAGE_TEXT;
		 
		 SET v_out = CONCAT('false,', @V_ERROR_MSG);
		 
		 CALL ETL.EDW_PROC_ERROR_LOG(P_DATA_DATE,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,@V_RETURN_CODE,@V_ERROR_MSG);
  END;
	
	IF v_period_flag = '1' THEN  
			SET V_END_DATE = DATE_FORMAT('20211201','%Y-%m-%d');
	ELSEIF v_period_flag = '2' THEN 
			SET V_END_DATE = DATE_FORMAT('20211201','%Y-%m');
	ELSEIF v_period_flag = '3' THEN 
			SET V_END_DATE = CONCAT(year('20211201'),'-0',quarter('20211201'));
	ELSEIF v_period_flag = '4' THEN 
			SET V_END_DATE = year('20211201');
	END IF;
	
	OPEN sqlText;
  WHILE
    done <> 1 DO FETCH sqlText INTO index_id, table_name, deleteSql, insertStr, selectStr, whereStr, buildType;
		IF done <> 1 THEN
				
				START TRANSACTION; 
				
				SET V_STEP_ID = 1;
				SET @del_sql = CONCAT('DELETE FROM ', table_name, ' WHERE PERIOD_FLAG=''', v_period_flag, ''' AND REPLACE(ACCOUNT_PERIOD,', '''Q''', ',''-0'')' , '<=', '''', V_END_DATE, '''');
				PREPARE delSql FROM @del_sql;
				EXECUTE delSql;
				DEALLOCATE PREPARE delSql;
				
				CALL ETL.EDW_PROC_TRACE_LOG(P_DATA_DATE,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());  
				
				SET V_STEP_ID = 2;
				SET @update_Sql_0 = REPLACE(updateStr,'@','''1''');
				PREPARE update_0 FROM @update_Sql_0;
				EXECUTE update_0;
				DEALLOCATE PREPARE update_0;
				
				CALL ETL.EDW_PROC_TRACE_LOG(P_DATA_DATE,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
				
				IF buildType = '1' THEN
					 SET selectStr = CONCAT(selectStr, ' WHERE PERIOD_FLAG=''', v_period_flag, ''' AND REPLACE(ACCOUNT_PERIOD,', '''Q''', ',''-0'')' , '<=', '''', V_END_DATE, '''');
					 SET whereStr = NULL;
				END IF;
				
				SET V_STEP_ID = 3;
				SET @insert_sql = CONCAT_ws('', insertStr, selectStr, whereStr);
				PREPARE insertSql FROM @insert_sql;
				EXECUTE insertSql;
				DEALLOCATE PREPARE insertSql;
				
				CALL ETL.EDW_PROC_TRACE_LOG(P_DATA_DATE,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
				
				SET V_STEP_ID = 4;
				SET @update_Sql_1 = REPLACE(updateStr,'@','''2''');
				PREPARE update_1 FROM @update_Sql_1;
				EXECUTE update_1;
				DEALLOCATE PREPARE update_1;
				
				CALL ETL.EDW_PROC_TRACE_LOG(P_DATA_DATE,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT()); 
		END IF;
	END WHILE;
  CLOSE sqlText;
	
	IF v_out IS NULL OR v_out = '' THEN
		SET v_out = CONCAT('success,','历史数据跑批已完成');
		COMMIT;
	ELSE
			ROLLBACK;
	END IF;
	
END
$$
DELIMITER ;

-- PROCEDURE `indicators_lib`.`p_exe_formula_xunhuan`
DROP PROCEDURE IF EXISTS `indicators_lib`.`p_exe_formula_xunhuan`;
DELIMITER $$
CREATE DEFINER=`dis`@`%` PROCEDURE `p_exe_formula_xunhuan`(IN start_date VARCHAR(10),IN end_date VARCHAR(10))
BEGIN

	WHILE start_date <= end_date
	DO 
	
	CALL indicators_lib.p_exe_formula(start_date);
	
	SET start_date = DATE_ADD(start_date,INTERVAL 1 DAY);

	END WHILE;


	END
$$
DELIMITER ;

-- PROCEDURE `indicators_lib`.`p_mth_report_xunhuan`
DROP PROCEDURE IF EXISTS `indicators_lib`.`p_mth_report_xunhuan`;
DELIMITER $$
CREATE DEFINER=`dis`@`%` PROCEDURE `p_mth_report_xunhuan`(IN START_DATE VARCHAR(10),IN END_DATE  VARCHAR(10))
BEGIN
	WHILE START_DATE <= END_DATE
	DO 
	
	
	CALL report.P_NEWS_FLASH_MONTH_REPORT_TEXT(DATE_FORMAT(LAST_DAY(start_date),'%Y-%m'));
	CALL report.P_NEWS_FLASH_MONTH_TEXT_NUMBER(START_DATE);
	
	CALL report.P_MONTH_REPORT_TEXT(DATE_FORMAT(LAST_DAY(start_date),'%Y-%m'));
	
	
        CALL report.P_QUARTER_REPORT_TEXT(CONCAT(YEAR(START_DATE),'Q',QUARTER(START_DATE)));
	
	SET start_date = DATE_ADD(start_date,INTERVAL 1 MONTH);
	
	END WHILE;
	END
$$
DELIMITER ;

-- PROCEDURE `indicators_lib`.`P_TRS_BUDGET_INCOME_COMPARE_XIN`
DROP PROCEDURE IF EXISTS `indicators_lib`.`P_TRS_BUDGET_INCOME_COMPARE_XIN`;
DELIMITER $$
CREATE DEFINER=`dis`@`%` PROCEDURE `P_TRS_BUDGET_INCOME_COMPARE_XIN`(IN V_DATA_DATE VARCHAR(6))
BEGIN
  
  
  
DELETE FROM EDW.TRS_BUDGET_INCOME_COMPARE WHERE DATA_DATE = V_DATA_DATE;

insert into EDW.TRS_BUDGET_INCOME_COMPARE
SELECT 
	 DATA_DATE
	,PROJECT
	,ROUND (SUM(T010101_RATE),4)
	,SUM(T010101_RANK)
	,ROUND (SUM(101_TATE),4)
	,SUM(101_RANK)
	,ROWS_ID
FROM 
(
SELECT 
	AA.DATA_DATE,
	AA.PROJECT,
	AA.T010101_RATE,
	@rank:=@rank+1 AS T010101_RANK,
	AA.101_TATE,
	AA.101_RANK,
	AA.ROWS_ID
FROM 
(
SELECT 
	a.DATA_DATE,
	CASE WHEN a.TREDSCR = '大连市' THEN '辽宁'
             WHEN a.TREDSCR = '青岛市' THEN '山东省' 
	     WHEN a.TREDSCR = '深圳市' THEN '广东省'
             WHEN a.TREDSCR = '宁波市' THEN '浙江省'
             WHEN a.TREDSCR = '厦门市' THEN '福建省'
             WHEN (a.TREDSCR = '新疆兵团' or a.TREDSCR = '新疆区') THEN '新疆区'
	     ELSE a.TREDSCR
	     END  AS PROJECT,
	(SUM(a.YEAR_AMT)-SUM(b.YEAR_AMT))/SUM(b.YEAR_AMT) AS T010101_RATE,
	'' AS 101_TATE,
	'' AS 101_RANK,
        A.ROWS_ID
FROM stg.trs_tmis_budget_income_provinces a
LEFT JOIN stg.trs_tmis_budget_income_provinces b
       ON b.data_Date = DATE_FORMAT(DATE_SUB(CONCAT(a.data_Date,'01'),INTERVAL 1 YEAR),'%Y%m')
       AND a.TRECODE = b.TRECODE
       AND a.SUBJECT_CODE = b.SUBJECT_CODE
WHERE a.data_Date = V_DATA_DATE
AND a.SUBJECT_CODE = 'T010101'
GROUP BY
        CASE WHEN a.TRECODE = '3501000000' THEN '0600000000'
             WHEN a.TRECODE = '3302000000' THEN '1500000000' 
	     WHEN a.TRECODE = '3801000000' THEN '1900000000'
             WHEN a.TRECODE = '3600000000' THEN '1100000000'
             WHEN a.TRECODE = '4000000000' THEN '1300000000'
						 WHEN (a.TRECODE = '3100000000' or a.TRECODE = '3000000000')  THEN '3000000000'
	     ELSE a.TRECODE
	     END
ORDER BY T010101_RATE  DESC
) AA ,(SELECT @rank:=0) BB
UNION ALL
(
SELECT 
	AA.DATA_DATE,
	AA.PROJECT,
	AA.T010101_RATE,
	AA.T010101_RANK,
	AA.101_TATE,
	@rank2:=@rank2+1  AS 101_RANK,
	AA.ROWS_ID
FROM 
(
SELECT 
	a.DATA_DATE,
	CASE WHEN a.TREDSCR = '大连市' THEN '辽宁'
             WHEN a.TREDSCR = '青岛市' THEN '山东省' 
	     WHEN a.TREDSCR = '深圳市' THEN '广东省'
             WHEN a.TREDSCR = '宁波市' THEN '浙江省'
             WHEN a.TREDSCR = '厦门市' THEN '福建省'
             WHEN (a.TREDSCR = '新疆兵团' or a.TREDSCR = '新疆区') THEN '新疆区'
	     ELSE a.TREDSCR
	     END  AS PROJECT,
	'' AS T010101_RATE,
	'' AS T010101_RANK,
	(SUM(a.YEAR_AMT)-SUM(b.YEAR_AMT))/SUM(b.YEAR_AMT) AS 101_TATE,
	A.ROWS_ID
FROM stg.trs_tmis_budget_income_provinces a
LEFT JOIN stg.trs_tmis_budget_income_provinces b
       ON b.data_Date = DATE_FORMAT(DATE_SUB(CONCAT(a.data_Date,'01'),INTERVAL 1 YEAR),'%Y%m')
       AND a.TRECODE = b.TRECODE
       AND a.SUBJECT_CODE = b.SUBJECT_CODE
,(SELECT @tate:=NULL,@rank:=0) c
WHERE A.DATA_DATE = V_DATA_DATE
AND a.SUBJECT_CODE = '101'
GROUP BY
        CASE WHEN a.TRECODE = '3501000000' THEN '0600000000'
             WHEN a.TRECODE = '3302000000' THEN '1500000000' 
	     WHEN a.TRECODE = '3801000000' THEN '1900000000'
             WHEN a.TRECODE = '3600000000' THEN '1100000000'
             WHEN a.TRECODE = '4000000000' THEN '1300000000'
						 WHEN (a.TRECODE = '3100000000' or a.TRECODE = '3000000000')  THEN '3000000000'
	     ELSE a.TRECODE
	     END
ORDER BY 101_TATE DESC
) AA ,(SELECT @rank2:=0) BB
) 
)A
GROUP BY 
        PROJECT;
             
