-- PROCEDURE `indicators_lib`.`p_xunhuan_formula`
DROP PROCEDURE IF EXISTS `indicators_lib`.`p_xunhuan_formula`;
DELIMITER $$
CREATE DEFINER=`root`@`localhost` PROCEDURE `p_xunhuan_formula`(in V_BATCH_DATE VARCHAR(10))
BEGIN
	DECLARE V_PROC_NAME     VARCHAR(80)   DEFAULT 'EDW.P_TRS_BUDGET_INCOME_COMPARE.PRC';
	DECLARE V_START_TIME    CHAR(19)      DEFAULT NOW();
	DECLARE V_STEP_ID       INT           DEFAULT 0;
	DECLARE P_DATA_DATE     VARCHAR(8)	DEFAULT	DATE_FORMAT(V_BATCH_DATE,'%Y-%m');
	
	DECLARE DONE             INT DEFAULT FALSE;	
	DECLARE V_DATA_DATE      VARCHAR(10);          
	DECLARE CUR_D_ACCT CURSOR FOR 
	select 
	distinct 
	if(
	date_format(d_acct,'%Y-%m-%d') is null,
	date_format(concat(d_acct,'01'),'%Y-%m-%d'),
	date_format(d_acct,'%Y-%m-%d')
	) as d_acct
	from 
	(
	SELECT D_ACCT 
	FROM STG.TRS_TMIS_BUDGET_INCOME
	WHERE BATCH_DATE = V_BATCH_DATE
	UNION ALL 
	SELECT D_ACCT 
	FROM STG.TRS_TMIS_BUDGET_PAYOUT
	WHERE BATCH_DATE = V_BATCH_DATE
	UNION ALL 
	SELECT D_ACCT 
	FROM STG.TRS_TMIS_STOCK
	WHERE BATCH_DATE = V_BATCH_DATE) a
	order by
	if(
	date_format(d_acct,'%Y-%m-%d') is null,
	date_format(concat(d_acct,'01'),'%Y-%m-%d'),
	date_format(d_acct,'%Y-%m-%d')
	);
	
	DECLARE CUR_MONTH CURSOR FOR 
	select 
	distinct 
	if(
	date_format(d_acct,'%Y-%m-%d') is null,
	date_format(concat(d_acct,'01'),'%Y-%m'),
	date_format(d_acct,'%Y-%m')
	) as d_acct
	from 
	(
	SELECT D_ACCT 
	FROM STG.TRS_TMIS_BUDGET_INCOME
	WHERE BATCH_DATE = V_BATCH_DATE
	UNION ALL 
	SELECT D_ACCT 
	FROM STG.TRS_TMIS_BUDGET_PAYOUT
	WHERE BATCH_DATE = V_BATCH_DATE
	UNION ALL 
	SELECT D_ACCT 
	FROM STG.TRS_TMIS_STOCK
	WHERE BATCH_DATE = V_BATCH_DATE) a
	order by
	if(
	date_format(d_acct,'%Y-%m-%d') is null,
	date_format(concat(d_acct,'01'),'%Y-%m-%d'),
	date_format(d_acct,'%Y-%m-%d')
	);
	
	DECLARE CONTINUE HANDLER FOR NOT FOUND SET DONE:= TRUE;
	
	DECLARE EXIT HANDLER FOR SQLEXCEPTION
	BEGIN
	GET DIAGNOSTICS CONDITION 1 @V_RETURN_CODE = RETURNED_SQLSTATE ,@V_ERROR_MSG = MESSAGE_TEXT;
	CALL ETL.EDW_PROC_ERROR_LOG(P_DATA_DATE,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,@V_RETURN_CODE,@V_ERROR_MSG);
	END; 
	
	
	 SET V_STEP_ID = 1;
	
	update STG.TRS_TMIS_BUDGET_INCOME 
	set D_ACCT = case when length(D_ACCT) = 6 
				then date_format(concat(D_ACCT,'01'),'%Y-%m-%d') 
				else date_format(D_ACCT,'%Y-%m-%d') end;
	 SET V_STEP_ID = 2;
	update STG.TRS_TMIS_BUDGET_PAYOUT 
	set D_ACCT = case when LENGTH(D_ACCT) = 6 
				then date_format(concat(D_ACCT,'01'),'%Y-%m-%d') 
				else date_format(D_ACCT,'%Y-%m-%d') end;
	 SET V_STEP_ID = 3;
	update STG.TRS_TMIS_STOCK set TRECODE = '2200000000' ,TREDSCR = '国家金库重庆市分库' where TRECODE = 'NNNNNNNNNN';
	
	 SET V_STEP_ID = 4;
	CALL edw.P_TRS_BUDGET_INCOME_COMPARE(date_format(V_BATCH_DATE,'%Y%m%d'));
	
	
	CALL edw.P_TRS_BUDGET_INCOME_COMPARE_XIN(date_format(V_BATCH_DATE,'%Y%m'));
	
	OPEN CUR_D_ACCT;
	ENTLOOP:LOOP
		FETCH CUR_D_ACCT INTO V_DATA_DATE;
		IF DONE THEN
		LEAVE ENTLOOP;
		END IF;
		
		 SET V_STEP_ID = 5;
		
	 	 CALL indicators_lib.p_exe_formula_hand(V_DATA_DATE,'e34ac06898ce11eab404000c298a21af'); 
		
	        
	         SET V_STEP_ID = 6;
	        IF V_DATA_DATE = concat(date_format(V_DATA_DATE,'%Y-%m'),'-01')
	        THEN
	        CALL indicators_lib.p_exe_formula(V_DATA_DATE); 
	        CALL report.P_QUARTER_REPORT_TEXT(CONCAT(YEAR(V_DATA_DATE),'Q',QUARTER(V_DATA_DATE)));
	        CALL report.P_NEWS_FLASH_QUARTER_REPORT_TEXT(CONCAT(YEAR(V_DATA_DATE),'Q',QUARTER(V_DATA_DATE)));
	        END IF;	
	
		END LOOP ENTLOOP;
		CLOSE CUR_D_ACCT;
		SET DONE = FALSE;
	
	OPEN CUR_MONTH;
	MONTHLOOP:LOOP
		FETCH CUR_MONTH INTO V_DATA_DATE;
		IF DONE THEN
		LEAVE MONTHLOOP;
		END IF;
		
	 	 SET V_STEP_ID = 7;
		call report.P_MONTH_REPORT_TEXT(V_DATA_DATE);
	        CALL report.P_NEWS_FLASH_MONTH_REPORT_TEXT(V_DATA_DATE);
	        CALL report.P_NEWS_FLASH_MONTH_TEXT_NUMBER(concat(V_DATA_DATE,'-01'));

	        
		END LOOP MONTHLOOP;
		CLOSE CUR_MONTH;
		SET DONE = FALSE;
	
	END
$$
DELIMITER ;

-- PROCEDURE `indicators_lib`.`p_xunhuan_formula_new`
DROP PROCEDURE IF EXISTS `indicators_lib`.`p_xunhuan_formula_new`;
DELIMITER $$
CREATE DEFINER=`root`@`localhost` PROCEDURE `p_xunhuan_formula_new`(IN V_BATCH_DATE VARCHAR(10))
BEGIN
	DECLARE V_PROC_NAME     VARCHAR(80)   DEFAULT 'EDW.p_xunhuan_formula_new.PRC';
	DECLARE V_START_TIME    CHAR(19)      DEFAULT NOW();
	DECLARE V_STEP_ID       INT           DEFAULT 0;
	DECLARE P_DATA_DATE     VARCHAR(8)	DEFAULT	DATE_FORMAT(CONCAT(V_BATCH_DATE,'01'),'%Y-%m');
	
	DECLARE DONE             INT DEFAULT FALSE;	
	DECLARE V_DATA_DATE      VARCHAR(10);          
	DECLARE CUR_D_ACCT CURSOR FOR 
		SELECT 
	DISTINCT 
	 
	DATE_FORMAT(CONCAT(REPLACE(d_acct,'-',''),''),'%Y-%m-%d')
	  AS d_acct
	FROM 
	(
	
	SELECT D_ACCT 
	FROM STG.TRS_TMIS_STOCK
	WHERE (data_date LIKE    CONCAT(V_BATCH_DATE,'%')
	OR data_date LIKE  CONCAT(DATE_FORMAT(CONCAT(REPLACE(DATE_FORMAT(CONCAT('202512','01'),'%Y-%m'),'-',''),'01'),'%Y%m'),'%')) )a
	

	;
	
	DECLARE CUR_MONTH CURSOR FOR 
	SELECT 
	DISTINCT 
	IF(
	DATE_FORMAT(d_acct,'%Y-%m-%d') IS NULL,

	DATE_FORMAT(CONCAT(REPLACE(d_acct,'-',''),'01'),'%Y-%m'),
	DATE_FORMAT(d_acct,'%Y-%m')
	) AS d_acct
	FROM 
	(
	SELECT D_ACCT 
	FROM STG.TRS_TMIS_BUDGET_INCOME
	WHERE DATA_DATE = CONCAT(V_BATCH_DATE)
	UNION ALL 
	SELECT D_ACCT 
	FROM STG.TRS_TMIS_BUDGET_PAYOUT
	WHERE DATA_DATE = CONCAT(V_BATCH_DATE)
	  )a
	ORDER BY
	IF(
	DATE_FORMAT(d_acct,'%Y-%m-%d') IS NULL,

DATE_FORMAT(CONCAT(REPLACE(d_acct,'-',''),'01'),'%Y-%m'),
	DATE_FORMAT(d_acct,'%Y-%m-%d')
	);
	
	DECLARE CONTINUE HANDLER FOR NOT FOUND SET DONE:= TRUE;
	
	DECLARE EXIT HANDLER FOR SQLEXCEPTION
	BEGIN
	GET DIAGNOSTICS CONDITION 1 @V_RETURN_CODE = RETURNED_SQLSTATE ,@V_ERROR_MSG = MESSAGE_TEXT;
	CALL ETL.EDW_PROC_ERROR_LOG(P_DATA_DATE,V_START_TIME,NOW(),'gk',V_STEP_ID,@V_RETURN_CODE,@V_ERROR_MSG);
	END; 
	
	
	 SET V_STEP_ID = 1;

	
	UPDATE STG.TRS_TMIS_BUDGET_INCOME 
	SET D_ACCT = CASE WHEN LENGTH(D_ACCT) = 6 
				THEN DATE_FORMAT(CONCAT(D_ACCT,'01'),'%Y-%m-%d') 
				ELSE DATE_FORMAT(D_ACCT,'%Y-%m-%d') END;
	CALL ETL.EDW_PROC_ERROR_LOG(P_DATA_DATE,V_START_TIME,NOW(),'gk',V_STEP_ID,@V_RETURN_CODE,'222');
	 SET V_STEP_ID = 2;
	UPDATE STG.TRS_TMIS_BUDGET_PAYOUT 
	SET D_ACCT = CASE WHEN LENGTH(D_ACCT) = 6 
				THEN DATE_FORMAT(CONCAT(D_ACCT,'01'),'%Y-%m-%d') 
				ELSE DATE_FORMAT(D_ACCT,'%Y-%m-%d') END;
			CALL ETL.EDW_PROC_ERROR_LOG(P_DATA_DATE,V_START_TIME,NOW(),'gk',V_STEP_ID,@V_RETURN_CODE,'33');

	 SET V_STEP_ID = 3;
	UPDATE STG.TRS_TMIS_STOCK SET TRECODE = '2200000000' ,TREDSCR = '国家金库重庆市分库' WHERE TRECODE = 'NNNNNNNNNN';

	
	 SET V_STEP_ID = 4;
	CALL edw.P_TRS_BUDGET_INCOME_COMPARE_NEW(DATE_FORMAT(CONCAT(V_BATCH_DATE,'01'),'%Y%m%d'));

	SET V_STEP_ID = 5;
	    CALL report.`p_trs_income_payout_statistics`(DATE_FORMAT(CONCAT(V_BATCH_DATE,'01'),'%Y%m%d'));

	    SET V_STEP_ID = 6;
	    CALL edw.P_TRS_FINANCE_TAX_STATIS_NEW(DATE_FORMAT(CONCAT(V_BATCH_DATE,'01'),'%Y%m%d'));

	 
	  
	
	OPEN CUR_D_ACCT;
	ENTLOOP:LOOP
		FETCH CUR_D_ACCT INTO V_DATA_DATE;
		IF DONE THEN
		LEAVE ENTLOOP;
		END IF;
SELECT 111;		
		

		
		 SET V_STEP_ID = 7;
		
	 	 CALL indicators_lib.p_exe_formula_hand(V_DATA_DATE,'e34ac06898ce11eab404000c298a21af'); 
	 	 CALL ETL.EDW_PROC_ERROR_LOG(P_DATA_DATE,V_START_TIME,NOW(),'gk',V_STEP_ID,@V_RETURN_CODE,'777');
		
		
	        
	         SET V_STEP_ID = 8;
	        IF V_DATA_DATE = CONCAT(DATE_FORMAT(V_DATA_DATE,'%Y-%m'),'-01')

	        THEN
	        CALL indicators_lib.p_exe_formula(V_DATA_DATE); 
	    
	        CALL report.P_QUARTER_REPORT_TEXT(CONCAT(YEAR(V_DATA_DATE),'Q',QUARTER(V_DATA_DATE)));
	        CALL report.P_NEWS_FLASH_QUARTER_REPORT_TEXT(CONCAT(YEAR(V_DATA_DATE),'Q',QUARTER(V_DATA_DATE)));
	        
	        END IF;	
	
		END LOOP ENTLOOP;
		CLOSE CUR_D_ACCT;
		SET DONE = FALSE;
	
	OPEN CUR_MONTH;
	MONTHLOOP:LOOP
		FETCH CUR_MONTH INTO V_DATA_DATE;
		IF DONE THEN
		LEAVE MONTHLOOP;
		END IF;
		
	 	 SET V_STEP_ID = 9;
		CALL report.P_MONTH_REPORT_TEXT(V_DATA_DATE);
	        CALL report.P_NEWS_FLASH_MONTH_REPORT_TEXT(V_DATA_DATE);
	        CALL report.P_NEWS_FLASH_MONTH_TEXT_NUMBER(CONCAT(V_DATA_DATE,'-01'));
	        CALL visual_screen.P_task_vscreen_new(V_BATCH_DATE);
	         CALL ETL.EDW_PROC_ERROR_LOG(P_DATA_DATE,V_START_TIME,NOW(),'gk',V_STEP_ID,@V_RETURN_CODE,'999');
	        
		END LOOP MONTHLOOP;
		CLOSE CUR_MONTH;
		SET DONE = FALSE;
	
	END
$$
DELIMITER ;

