	UPDATE STG.TRS_TMIS_BUDGET_PAYOUT 
	SET D_ACCT = CASE WHEN LENGTH(D_ACCT) = 6 
				THEN DATE_FORMAT(CONCAT(D_ACCT,'01'),'%Y-%m-%d') 
				ELSE DATE_FORMAT(D_ACCT,'%Y-%m-%d') END;
			CALL ETL.EDW_PROC_ERROR_LOG(P_DATA_DATE,V_START_TIME,NOW(),'gk',V_STEP_ID,@V_RETURN_CODE,'33');

	 SET V_STEP_ID = 3;
	UPDATE STG.TRS_TMIS_STOCK SET TRECODE = '2200000000' ,TREDSCR = '国家金库重庆市分库' WHERE TRECODE = 'NNNNNNNNNN';

	
	 SET V_STEP_ID = 4;
	CALL edw.P_TRS_BUDGET_INCOME_COMPARE_NEW(DATE_FORMAT(CONCAT(V_BATCH_DATE,'01'),'%Y%m%d'));

	SET V_STEP_ID = 5;
	    CALL report.`p_trs_income_payout_statistics`(DATE_FORMAT(CONCAT(V_BATCH_DATE,'01'),'%Y%m%d'));

	    SET V_STEP_ID = 6;
	    CALL edw.P_TRS_FINANCE_TAX_STATIS_NEW(DATE_FORMAT(CONCAT(V_BATCH_DATE,'01'),'%Y%m%d'));

	 
	  
	
	OPEN CUR_D_ACCT;
	ENTLOOP:LOOP
		FETCH CUR_D_ACCT INTO V_DATA_DATE;
		IF DONE THEN
		LEAVE ENTLOOP;
		END IF;
SELECT 111;		
		

		
		 SET V_STEP_ID = 7;
		
	 	 CALL indicators_lib.p_exe_formula_hand(V_DATA_DATE,'e34ac06898ce11eab404000c298a21af'); 
	 	 CALL ETL.EDW_PROC_ERROR_LOG(P_DATA_DATE,V_START_TIME,NOW(),'gk',V_STEP_ID,@V_RETURN_CODE,'777');
		
		
	        
	         SET V_STEP_ID = 8;
	        IF V_DATA_DATE = CONCAT(DATE_FORMAT(V_DATA_DATE,'%Y-%m'),'-01')

	        THEN
	        CALL indicators_lib.p_exe_formula(V_DATA_DATE); 
	    
	        CALL report.P_QUARTER_REPORT_TEXT(CONCAT(YEAR(V_DATA_DATE),'Q',QUARTER(V_DATA_DATE)));
	        CALL report.P_NEWS_FLASH_QUARTER_REPORT_TEXT(CONCAT(YEAR(V_DATA_DATE),'Q',QUARTER(V_DATA_DATE)));
	        
	        END IF;	
	
		END LOOP ENTLOOP;
		CLOSE CUR_D_ACCT;
		SET DONE = FALSE;
	
	OPEN CUR_MONTH;
	MONTHLOOP:LOOP
		FETCH CUR_MONTH INTO V_DATA_DATE;
		IF DONE THEN
		LEAVE MONTHLOOP;
		END IF;
		
	 	 SET V_STEP_ID = 9;
		CALL report.P_MONTH_REPORT_TEXT(V_DATA_DATE);
	        CALL report.P_NEWS_FLASH_MONTH_REPORT_TEXT(V_DATA_DATE);
	        CALL report.P_NEWS_FLASH_MONTH_TEXT_NUMBER(CONCAT(V_DATA_DATE,'-01'));
	        CALL visual_screen.P_task_vscreen_new(V_BATCH_DATE);
	         CALL ETL.EDW_PROC_ERROR_LOG(P_DATA_DATE,V_START_TIME,NOW(),'gk',V_STEP_ID,@V_RETURN_CODE,'999');
	        
		END LOOP MONTHLOOP;
		CLOSE CUR_MONTH;
		SET DONE = FALSE;
	
	END
$$
DELIMITER ;

-- PROCEDURE `indicators_lib`.`p_xunhuan_formula_temp`
DROP PROCEDURE IF EXISTS `indicators_lib`.`p_xunhuan_formula_temp`;
DELIMITER $$
CREATE DEFINER=`root`@`%` PROCEDURE `p_xunhuan_formula_temp`(IN START_DATE VARCHAR(10),IN END_DATE  VARCHAR(10))
BEGIN
	while START_DATE <= END_DATE
	do 
	
	


	call report.P_MONTH_REPORT_TEXT(date_format(START_DATE,'%Y-%m'));
	call report.P_NEWS_FLASH_MONTH_REPORT_TEXT(DATE_FORMAT(START_DATE,'%Y-%m'));
	CALL report.P_QUARTER_REPORT_TEXT(concat(year(START_DATE),'Q',quarter(START_DATE)));
	CALL report.P_NEWS_FLASH_QUARTER_REPORT_TEXT(CONCAT(YEAR(START_DATE),'Q',QUARTER(START_DATE)));
	call report.P_NEWS_FLASH_MONTH_TEXT_NUMBER(START_DATE);
	
	



        SET start_date = DATE_ADD(start_date,INTERVAL 1 day);
        select start_date;
	 
	END WHILE;
	END
$$
DELIMITER ;

-- PROCEDURE `indicators_lib`.`p_xunhuan_formula_temp_2`
