	END WHILE;
	END
$$
DELIMITER ;

-- PROCEDURE `indicators_lib`.`xunhuan_lib`
DROP PROCEDURE IF EXISTS `indicators_lib`.`xunhuan_lib`;
DELIMITER $$
CREATE DEFINER=`root`@`%` PROCEDURE `xunhuan_lib`(IN s_date VARCHAR(10),IN e_date VARCHAR(10))
BEGIN

DECLARE V_STEP_ID       INT           DEFAULT 0; 
DECLARE V_PROC_NAME     VARCHAR(80)   DEFAULT 'indicators_lib.xunhuan_lib.PRC';
DECLARE V_START_TIME    CHAR(19)      DEFAULT NOW();
    
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        GET DIAGNOSTICS CONDITION 1 @V_RETURN_CODE = RETURNED_SQLSTATE ,@V_ERROR_MSG = MESSAGE_TEXT;
        CALL ETL.EDW_PROC_ERROR_LOG(DATE_FORMAT(V_START_TIME,'%Y-%m'),V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,@V_RETURN_CODE,@V_ERROR_MSG);
        CALL ETL.EDW_PROC_TRACE_LOG(DATE_FORMAT(V_START_TIME,'%Y-%m'),V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
    END;
      
WHILE s_date <= e_date
DO
SELECT s_date;
CALL indicators_lib.p_exe_formula_hand(s_date,'5a0d65f7309f11eb830e000c29587404');
commit;
 
SET s_date = LAST_DAY(DATE_ADD(s_date,INTERVAL 1 MONTH));
END WHILE;
	END
$$
DELIMITER ;

-- PROCEDURE `ods`.`p_create_table`
DROP PROCEDURE IF EXISTS `ods`.`p_create_table`;
DELIMITER $$
CREATE DEFINER=`root`@`%` PROCEDURE `p_create_table`( IN a INT(2)
)
BEGIN
	DECLARE V_STEP_ID       INT           DEFAULT 0; 
	DECLARE V_PROC_NAME     VARCHAR(80)   DEFAULT 'ods.p_create_table.PRC';
	DECLARE V_START_TIME    CHAR(19)      DEFAULT NOW();
	DECLARE V_KPI_ID    CHAR(50)      DEFAULT NOW();
	
  
    WHILE a<=31
    
   DO
	SET @aaa = CONCAT("CREATE TABLE test.tv_fin_income_detail_2019_",a," as select * from test.tv_fin_income_detail
	where S_INTREDATE = '2019-01-",IF(a<10,CONCAT('0',a),a),"'");
 
 
 
  
	PREPARE SQLaaa FROM @aaa;
	EXECUTE SQLaaa;
	DEALLOCATE PREPARE SQLaaa;
	
	SET a=a+1;
 
  END WHILE;
  
  
  
COMMIT;
   
	END
$$
DELIMITER ;

