	 (SELECT a.`INDEX_VALUE` FROM `indicators_lib`.`lib_indicators_000001` a
	  WHERE a.PERIOD_FLAG = '2'
		    AND DIMENSION_FLAG = '2'
		    AND INDEX_DIM_CODE = '500000'
		    AND ACCOUNT_PERIOD=v_data_date
		    ) AS lib_000001,
