	  WHERE a.PERIOD_FLAG = '2'
		    AND DIMENSION_FLAG = '2'
		    AND INDEX_DIM_CODE = '500000'
		    AND ACCOUNT_PERIOD=v_data_date) AS lib_000002,
		     (SELECT a.`INDEX_VALUE` FROM  `indicators_lib`.`lib_indicators_000003` a
	  WHERE a.PERIOD_FLAG = '2'
		    AND DIMENSION_FLAG = '2'
		    AND INDEX_DIM_CODE = '500000'
		    AND ACCOUNT_PERIOD=v_data_date) AS lib_000003,
		    1  AS lib_000004,
		    (SELECT a.`INDEX_VALUE` FROM  `indicators_lib`.`lib_indicators_000005` a
	  WHERE a.PERIOD_FLAG = '2'
		    AND DIMENSION_FLAG = '2'
		    AND INDEX_DIM_CODE = '500000'
		    AND ACCOUNT_PERIOD=v_data_date) AS lib_000005,
		     (SELECT a.`INDEX_VALUE` FROM  `indicators_lib`.`lib_indicators_000006` a
	  WHERE a.PERIOD_FLAG = '2'
		    AND DIMENSION_FLAG = '2'
