        WHERE a.DIMENSION_FLAG = '1'
        AND  a.PERIOD_FLAG = '2' AND ACCOUNT_PERIOD =v_data_date
        AND a.INDEX_DIM_CODE='2200000000')  AS '000452',
        (SELECT
        a.`INDEX_VALUE`
        FROM
        `indicators_lib`.`lib_indicators_000453` a
        WHERE a.DIMENSION_FLAG = '1'
        AND  a.PERIOD_FLAG = '2' AND ACCOUNT_PERIOD =v_data_date
        AND a.INDEX_DIM_CODE='2200000000')  AS '000453',
         (SELECT
        a.`INDEX_VALUE`
        FROM
        `indicators_lib`.`lib_indicators_000258` a
        WHERE a.DIMENSION_FLAG = '2'
        AND  a.PERIOD_FLAG = '2' AND ACCOUNT_PERIOD =v_data_date
        AND a.INDEX_DIM_CODE='500000')  AS '000258'
	   ,'2' AS  PERIOD_FLAG
	      ,'2' AS  DIMENSION_FLAG     
	      
	      
	              
	    ;
    
    
    
  
END
$$
DELIMITER ;

