-- PROCEDURE `report`.`p_trs_income_payout_statistics`
DROP PROCEDURE IF EXISTS `report`.`p_trs_income_payout_statistics`;
DELIMITER $$
CREATE DEFINER=`dis`@`%` PROCEDURE `p_trs_income_payout_statistics`(IN V_DATA_DATE VARCHAR(20))
BEGIN
	DECLARE P_DATA_DATE  VARCHAR(20)    DEFAULT DATE_FORMAT(v_data_date,'%Y-%m');
	DECLARE P_START_TIME CHAR(19)       DEFAULT NOW();
	DECLARE P_PROC_NAME  VARCHAR(50)    DEFAULT 'report.p_trs_income_statistics.proc';
	DECLARE P_STEP_ID    INT(2);
	
	DECLARE EXIT HANDLER FOR SQLEXCEPTION
	BEGIN 
		GET DIAGNOSTICS CONDITION 1 @V_RETURN_CODE = RETURNED_SQLSTATE ,@V_ERROR_MSG = MESSAGE_TEXT;
		CALL ETL.EDW_PROC_ERROR_LOG(P_DATA_DATE,p_START_TIME,NOW(),P_PROC_NAME,p_STEP_ID,@V_RETURN_CODE,@V_ERROR_MSG);
	END;   
SET P_STEP_ID = 1;
DELETE FROM REPORT.TRS_INCOME_PAYOUT_STATISTICS_INDEX WHERE ACCOUNT_PERIOD = DATE_FORMAT(V_DATA_DATE,'%Y-%m');
SET P_STEP_ID = 2;
INSERT INTO REPORT.TRS_INCOME_PAYOUT_STATISTICS_INDEX
(
  ACCOUNT_PERIOD
  ,INDEX_DIM_CODE
  ,INDEX_DIM_DESCR
  ,DIMENSION_FLAG
  ,PERIOD_FLAG
  ,SUBJECT_CODE
  ,SUBJECT_DSCR
  ,INDEX_VALUE
  ,AMOUNT_RATIO
  ,ADD_USERID
  ,ADD_DATE
  ,MODIFY_USERID
  ,MODIFY_DATE
  ,TYPE
)
SELECT 
 D_ACCT,
 INDEX_DIM_CODE,
 INDEX_DIM_DESCR,
 DIMENSION_FLAG,
 PERIOD_FLAG,
 SUBJECT_CODE,
 SUBJECT_DSCR,
 INDEX_VALUE,
 AMOUNT_RATIO,
 '',
 '',
 NOW(),
 '',
 '1'
FROM
(
SELECT
  a.*,
  IF(@p=a.INDEX_DIM_CODE,@RANK:=@RANK+1,@RANK:=1)   AS RANK,
  @p:=a.INDEX_DIM_CODE	
FROM
(
SELECT 
    a3.D_ACCT  				AS D_ACCT,
    a3.INDEX_DIM_CODE			AS INDEX_DIM_CODE,
    a3.INDEX_DIM_DESCR 			AS INDEX_DIM_DESCR,
    a3.INDEX_VALUE 			AS INDEX_VALUE ,
    a3.INDEX_VALUE/a2.INDEX_VALUE  AS AMOUNT_RATIO,
    a3.SUBJECT_CODE 			AS SUBJECT_CODE,
    a3.SUBJECT_DSCR		AS SUBJECT_DSCR	,
    a3.	DIMENSION_FLAG  	AS DIMENSION_FLAG,
    a3. PERIOD_FLAG		AS PERIOD_FLAG
FROM 
(
SELECT  DATE_FORMAT(V_DATA_DATE,'%Y-%m') AS D_ACCT,
	a1.PID 				  AS INDEX_DIM_CODE,
	a1.GUOKU_DSCR			  AS INDEX_DIM_DESCR,
	ROUND(SUM(a0.THIS_AMT),4)         AS INDEX_VALUE,
	a0.SUBJECT_CODE  		  AS SUBJECT_CODE,
	a0.SUBJECT_DSCR			  AS SUBJECT_DSCR,
	'1'				  AS DIMENSION_FLAG,
	'2'				  AS PERIOD_FLAG
    FROM STG.trs_tmis_budget_income a0
	LEFT JOIN (
	SELECT 
	DISTINCT 
	p.GUOKU_ID AS PID,
	p.LEVEL,
	p.GUOKU_DSCR,
	c.GUOKU_ID AS CID
	FROM edw.cm_guoku_dimnsn p
	JOIN edw.cm_guoku_dimnsn c
	ON p.GUOKU_LVL_ID_2 = c.GUOKU_LVL_ID_1
	OR  p.GUOKU_LVL_ID_3 = c.GUOKU_LVL_ID_2 
	OR  p.GUOKU_ID = c.GUOKU_LVL_ID_3) a1 
	ON a0.TRECODE = a1.CID
    LEFT JOIN edw.cm_guoku_rcpt_dsb rc
        ON a0.SUBJECT_CODE = rc.SUBJECT_CODE_4
    WHERE DATE_FORMAT(a0.D_ACCT,'%Y-%m') = DATE_FORMAT(V_DATA_DATE,'%Y-%m') 
        AND a0.SUBJECT_CODE LIKE '101__'
	AND a0.LEVEL >= a1.LEVEL
	AND a0.TRECODE NOT IN('2231000000','2232000000','2233000000','2230000000') 
     GROUP BY 
	DATE_FORMAT(a0.D_ACCT,'%Y-%m'),
	a0.SUBJECT_CODE,
	a1.PID 
     UNION ALL 
   
      SELECT  DATE_FORMAT(V_DATA_DATE,'%Y-%m') AS D_ACCT,
	a1.AREA_NO_ID 			  AS INDEX_DIM_CODE,
	a1.AREA_DSCR			  AS INDEX_DIM_DESCR,
	ROUND(SUM(a0.THIS_AMT),4)         AS INDEX_VALUE,
	a0.SUBJECT_CODE  		  AS SUBJECT_CODE,
	a0.SUBJECT_DSCR			  AS SUBJECT_DSCR,
	'2'				  AS DIMENSION_FLAG,
	'2'				  AS PERIOD_FLAG
    FROM STG.trs_tmis_budget_income a0
	LEFT JOIN (
	SELECT 
	DISTINCT 
	p.GUOKU_ID AS PID,
	P.AREA_NO_ID AS AREA_NO_ID, 
	p.LEVEL,
	p.GUOKU_DSCR,
	p.AREA_DSCR,
	c.GUOKU_ID AS CID
	FROM edw.cm_guoku_dimnsn p
	JOIN edw.cm_guoku_dimnsn c
	ON p.GUOKU_LVL_ID_2 = c.GUOKU_LVL_ID_1
	OR  p.GUOKU_LVL_ID_3 = c.GUOKU_LVL_ID_2 
	OR  p.GUOKU_ID = c.GUOKU_LVL_ID_3) a1 
	ON a0.TRECODE = a1.CID
    LEFT JOIN edw.cm_guoku_rcpt_dsb rc
        ON a0.SUBJECT_CODE = rc.SUBJECT_CODE_4
    WHERE DATE_FORMAT(a0.D_ACCT,'%Y-%m') = DATE_FORMAT(V_DATA_DATE,'%Y-%m') 
        AND a0.SUBJECT_CODE LIKE '101__'
	AND a0.LEVEL >= a1.LEVEL
	AND a0.TRECODE NOT IN('2231000000','2232000000','2233000000','2230000000') 
     GROUP BY 
	DATE_FORMAT(a0.D_ACCT,'%Y-%m'),
	a1.AREA_NO_ID ,
	a0.SUBJECT_CODE	
	) a3	
		
	LEFT JOIN(
	
		SELECT DATE_FORMAT(V_DATA_DATE,'%Y-%m') AS D_ACCT,
	a1.PID AS INDEX_DIM_CODE,
	a1.GUOKU_DSCR AS INDEX_DIM_DESCR,
	ROUND(SUM(a0.THIS_AMT),4) AS INDEX_VALUE,
	a0.SUBJECT_CODE,
	a0.SUBJECT_DSCR,
	'1',
	'2'
    FROM STG.trs_tmis_budget_income a0
	LEFT JOIN (
	SELECT 
	DISTINCT 
	p.GUOKU_ID AS PID,
	p.LEVEL,
	p.GUOKU_DSCR,
	c.GUOKU_ID AS CID
	FROM edw.cm_guoku_dimnsn p
	JOIN edw.cm_guoku_dimnsn c
	ON p.GUOKU_LVL_ID_2 = c.GUOKU_LVL_ID_1
	OR  p.GUOKU_LVL_ID_3 = c.GUOKU_LVL_ID_2 
	OR  p.GUOKU_ID = c.GUOKU_LVL_ID_3) a1 
	ON a0.TRECODE=a1.CID
    WHERE DATE_FORMAT(a0.D_ACCT,'%Y-%m')=DATE_FORMAT(V_DATA_DATE,'%Y-%m') 
        AND a0.SUBJECT_CODE = '101'
        AND a0.LEVEL >= a1.LEVEL
	AND a0.TRECODE NOT IN('2231000000','2232000000','2233000000','2230000000') 
     GROUP BY 
	DATE_FORMAT(a0.D_ACCT,'%Y-%m'),
	a0.SUBJECT_CODE,   
	a1.PID 
     UNION ALL
     
      SELECT DATE_FORMAT(V_DATA_DATE,'%Y-%m') AS D_ACCT,
	a1.AREA_NO_ID AS INDEX_DIM_CODE,
	a1.AREA_DSCR AS INDEX_DIM_DESCR,
	ROUND(SUM(a0.THIS_AMT),4) AS INDEX_VALUE,
	a0.SUBJECT_CODE,
	a0.SUBJECT_DSCR,
	'2',
	'2'
    FROM STG.trs_tmis_budget_income a0
	LEFT JOIN (
	SELECT 
	DISTINCT 
	p.GUOKU_ID AS PID,
	p.AREA_NO_ID AS AREA_NO_ID,
	p.LEVEL,
	p.GUOKU_DSCR,
	p.AREA_DSCR,
	c.GUOKU_ID AS CID
	FROM edw.cm_guoku_dimnsn p
	JOIN edw.cm_guoku_dimnsn c
	ON p.GUOKU_LVL_ID_2 = c.GUOKU_LVL_ID_1
	OR  p.GUOKU_LVL_ID_3 = c.GUOKU_LVL_ID_2 
	OR  p.GUOKU_ID = c.GUOKU_LVL_ID_3) a1 
	ON a0.TRECODE=a1.CID
    WHERE DATE_FORMAT(a0.D_ACCT,'%Y-%m')=DATE_FORMAT(V_DATA_DATE,'%Y-%m') 
        AND a0.SUBJECT_CODE = '101'
        AND a0.LEVEL >= a1.LEVEL
	AND a0.TRECODE NOT IN('2231000000','2232000000','2233000000','2230000000') 
     GROUP BY 
     DATE_FORMAT(a0.D_ACCT,'%Y-%m'),
     a1.AREA_NO_ID,
     a0.SUBJECT_CODE    
	) a2
        ON a3.D_ACCT = a2.D_ACCT
        AND a3.INDEX_DIM_CODE = a2.INDEX_DIM_CODE                        
        WHERE 
        a3.D_ACCT  = DATE_FORMAT(V_DATA_DATE,'%Y-%m')
        GROUP BY a3.INDEX_DIM_CODE,a3.SUBJECT_CODE
        ORDER BY a3.INDEX_DIM_CODE,a3.INDEX_VALUE/a2.INDEX_VALUE DESC 
     )   a
,(SELECT @p:=NULL,@rank:=0) rank
  )a 
  WHERE a.rank <= 8;
  
  SET P_STEP_ID = 3;
  
