INSERT INTO REPORT.TRS_INCOME_PAYOUT_STATISTICS(
		 ACCOUNT_PERIOD
		,INDEX_DIM_CODE		
		,INDEX_DIM_DESCR
		,DIMENSION_FLAG
		,PERIOD_FLAG
		,SUBJECT_CODE
		,SUBJECT_DSCR
		,INDEX_VALUE
		,VALUE_YEAR
		,AMOUNT_RATIO
		,ADD_USERID
		,ADD_DATE
		,MODIFY_USERID
		,MODIFY_DATE
		,TYPE
	)
	
 SELECT 
	sta1.ACCOUNT_PERIOD AS ACCOUNT_PERIOD,
	sta1.INDEX_DIM_CODE AS INDEX_DIM_CODE,
	sta1.INDEX_DIM_DESCR AS INDEX_DIM_DESCR,
	sta1.DIMENSION_FLAG AS DIMENSION_FLAG,
	sta1.PERIOD_FLAG AS PERIOD_FLAG,
	sta1.SUBJECT_CODE AS SUBJECT_CODE,
	sta1.SUBJECT_DSCR AS SUBJECT_DSCR,
	sta1.INDEX_VALUE AS INDEX_VALUE,
	((sta1.INDEX_VALUE - sta2.INDEX_VALUE)/sta2.INDEX_VALUE) AS VALUE_YEAR,
	sta1.AMOUNT_RATIO AS AMOUNT_RATIO,
	'',
	NOW(),
	'',
	'',
	STA1.TYPE
 FROM report.trs_income_payout_statistics_index sta1
LEFT JOIN 
(
    SELECT  
        DATE_FORMAT(DATE_SUB(V_DATA_DATE,INTERVAL 1 YEAR),'%Y-%m') AS D_ACCT,
	a1.PID 				  AS INDEX_DIM_CODE,
	a1.GUOKU_DSCR			  AS INDEX_DIM_DESCR,
