	a0.SUBJECT_CODE  		  AS SUBJECT_CODE,
	a0.SUBJECT_DSCR			  AS SUBJECT_DSCR
    FROM STG.trs_tmis_budget_income a0
	LEFT JOIN (
	SELECT 
	DISTINCT 
