	LEFT JOIN (
	SELECT 
	DISTINCT 
	p.GUOKU_ID AS PID,
	P.AREA_NO_ID AS AREA_NO_ID, 
	p.LEVEL,
	p.GUOKU_DSCR,
	p.AREA_DSCR,
	c.GUOKU_ID AS CID
	FROM edw.cm_guoku_dimnsn p
	JOIN edw.cm_guoku_dimnsn c
	ON p.GUOKU_LVL_ID_2 = c.GUOKU_LVL_ID_1
	OR  p.GUOKU_LVL_ID_3 = c.GUOKU_LVL_ID_2 
	OR  p.GUOKU_ID = c.GUOKU_LVL_ID_3) a1 
	ON a0.TRECODE = a1.CID
    LEFT JOIN edw.cm_guoku_rcpt_dsb rc
        ON a0.SUBJECT_CODE = rc.SUBJECT_CODE_4
    WHERE DATE_FORMAT(a0.D_ACCT,'%Y-%m') = DATE_FORMAT(DATE_SUB(V_DATA_DATE,INTERVAL 1 YEAR),'%Y-%m') 
        AND a0.SUBJECT_CODE LIKE '2__'
	AND a0.LEVEL >= a1.LEVEL
	AND a0.TRECODE NOT IN('2231000000','2232000000','2233000000','2230000000') 
     GROUP BY 
	DATE_FORMAT(a0.D_ACCT,'%Y-%m'),
	a1.AREA_NO_ID ,
	a0.SUBJECT_CODE	
)  sta2
	ON  sta1.INDEX_DIM_CODE=sta2.INDEX_DIM_CODE
	AND STA1.SUBJECT_CODE = STA2.SUBJECT_CODE
WHERE sta1.ACCOUNT_PERIOD = DATE_FORMAT(V_DATA_DATE,'%Y-%m');
   
	END
$$
DELIMITER ;

-- PROCEDURE `report`.`p_trs_lib_alter_table`
DROP PROCEDURE IF EXISTS `report`.`p_trs_lib_alter_table`;
DELIMITER $$
CREATE DEFINER=`root`@`%` PROCEDURE `p_trs_lib_alter_table`(
)
BEGIN
	DECLARE V_STEP_ID       INT           DEFAULT 0; 
	DECLARE V_PROC_NAME     VARCHAR(80)   DEFAULT 'REPORT.P_TRS_LIB_ALTER_TABLE.PRC';
	DECLARE V_START_TIME    CHAR(19)      DEFAULT NOW();
	DECLARE V_KPI_ID    CHAR(50)      DEFAULT NOW();
	
	DECLARE DONE INT DEFAULT FALSE; 
	DECLARE MY_CURSOR CURSOR FOR (
		SELECT DISTINCT
		  TABLE_NAME AS kpi_id
		FROM
		  information_schema.`TABLES` a
		WHERE a.`TABLE_SCHEMA` = 'indicators_lib'
		  AND a.`TABLE_NAME` LIKE 'lib_indicators_%'
		  );
  
	DECLARE CONTINUE HANDLER FOR NOT FOUND SET DONE = TRUE; 
 
	 
	OPEN MY_CURSOR; 
	MY_CURSOR: LOOP
    FETCH MY_CURSOR INTO V_KPI_ID ;
    IF DONE THEN 
      LEAVE MY_CURSOR; 
    END IF; 
    
SET V_STEP_ID = 1; 
 SET @sql_drop_table =  CONCAT("ALTER TABLE   indicators_lib.",V_KPI_ID," ADD C_BDGLEVEL VARCHAR(2) COLLATE utf8_bin DEFAULT '' COMMENT '级次(1中央级，2省级，3市级，4县（区）级，5乡（镇）级，6地方级，7全国)',
ADD JURISDICTION VARCHAR(10) COLLATE utf8_bin DEFAULT NULL COMMENT '辖属标识(全辖，本级)';");
PREPARE DROP_SQLTXT FROM @sql_drop_table;
EXECUTE DROP_SQLTXT;
DEALLOCATE PREPARE DROP_SQLTXT;  
    COMMIT;
  
 
  
COMMIT;
 
  END LOOP MY_CURSOR; 
  CLOSE MY_CURSOR;
   
	END
$$
DELIMITER ;

