-- PROCEDURE `report`.`p_trs_lib_create_table`
DROP PROCEDURE IF EXISTS `report`.`p_trs_lib_create_table`;
DELIMITER $$
CREATE DEFINER=`root`@`%` PROCEDURE `p_trs_lib_create_table`(
)
BEGIN
	DECLARE V_STEP_ID       INT           DEFAULT 0; 
	DECLARE V_PROC_NAME     VARCHAR(80)   DEFAULT 'REPORT.P_TRS_LIB_CREATE_TABLE.PRC';
	DECLARE V_START_TIME    CHAR(19)      DEFAULT NOW();
	DECLARE V_KPI_ID    CHAR(50)      DEFAULT NOW();
	
	DECLARE DONE INT DEFAULT FALSE; 
	DECLARE MY_CURSOR CURSOR FOR (
	SELECT DISTINCT create_table as kpi_id
		  FROM report.indicators_lib_create_all a    WHERE CAST(a.create_table AS SIGNED) > 258  ORDER BY CAST(a.create_table AS SIGNED)  
	   );
  
	DECLARE CONTINUE HANDLER FOR NOT FOUND SET DONE = TRUE; 
 
	 
	OPEN MY_CURSOR; 
	MY_CURSOR: LOOP
    FETCH MY_CURSOR INTO V_KPI_ID ;
    IF DONE THEN 
      LEAVE MY_CURSOR; 
    END IF; 
    
SET V_STEP_ID = 1; 
 SET @sql_drop_table =  CONCAT("DROP TABLE  IF EXISTS  indicators_lib.lib_indicators_",V_KPI_ID);
PREPARE DROP_SQLTXT FROM @sql_drop_table;
EXECUTE DROP_SQLTXT;
DEALLOCATE PREPARE DROP_SQLTXT;  
    COMMIT;
    
   SET V_STEP_ID = 2; 
   
SET @sql_create_table = CONCAT("CREATE TABLE indicators_lib.lib_indicators_",V_KPI_ID," (
  `INDEX_ID` VARCHAR(32) COLLATE utf8_bin DEFAULT NULL COMMENT '指标id',
  `ACCOUNT_PERIOD` VARCHAR(10) COLLATE utf8_bin DEFAULT NULL COMMENT '账期',
  `INDEX_DIM_CODE` VARCHAR(12) COLLATE utf8_bin DEFAULT NULL COMMENT '指标维度编码',
  `INDEX_DIM_DESCR` VARCHAR(100) COLLATE utf8_bin DEFAULT NULL COMMENT '指标维度描述',
  `DIMENSION_FLAG` VARCHAR(2) COLLATE utf8_bin DEFAULT NULL COMMENT '维度标识(1国库，2地区，3核算主体)',
  `PERIOD_FLAG` VARCHAR(2) COLLATE utf8_bin DEFAULT NULL COMMENT '周期标识(1日，2月，3季，4年)',
  `C_BDGLEVEL` VARCHAR(2) COLLATE utf8_bin DEFAULT '' COMMENT '级次(1中央级，2省级，3市级，4县（区）级，5乡（镇）级，6地方级，7全国)',
  `JURISDICTION` VARCHAR(10) COLLATE utf8_bin DEFAULT NULL COMMENT '辖属标识(全辖，本级)',
  `INDEX_VALUE` DECIMAL(28,4) DEFAULT NULL COMMENT '指标值',
  `ADD_USERID` VARCHAR(32) COLLATE utf8_bin DEFAULT NULL COMMENT '新增人ID',
  `ADD_DATE` VARCHAR(20) COLLATE utf8_bin DEFAULT NULL COMMENT '新增时间',
  `MODIFY_USERID` VARCHAR(32) COLLATE utf8_bin DEFAULT NULL COMMENT '修改人ID',
  `MODIFY_DATE` VARCHAR(20) COLLATE utf8_bin DEFAULT NULL COMMENT '修改时间'
) ENGINE=INNODB DEFAULT CHARSET=utf8 COLLATE=utf8_bin ROW_FORMAT=DYNAMIC COMMENT=''
 ;");
  
PREPARE SQLTXT FROM @sql_create_table;
EXECUTE SQLTXT;
DEALLOCATE PREPARE SQLTXT;
 
  
COMMIT;
 
  END LOOP MY_CURSOR; 
  CLOSE MY_CURSOR;
   
	END
$$
DELIMITER ;

-- FUNCTION `seo`.`f_get_IndexName`
DROP FUNCTION IF EXISTS `seo`.`f_get_IndexName`;
DELIMITER $$
CREATE DEFINER=`dis`@`%` FUNCTION `f_get_IndexName`(schemeColumns VARCHAR(1000)) RETURNS varchar(2000) CHARSET utf8
BEGIN
			DECLARE indexName VARCHAR(2000) DEFAULT '';
			
			SELECT GROUP_CONCAT(INDEX_NAME ORDER BY INSTR(schemeColumns,r.INDEX_ID)) INTO indexName FROM 
			indicators_lib.`lib_index_relation` r WHERE INSTR(schemeColumns,r.INDEX_ID) > 0;
			IF indexName IS NULL THEN 
					SET indexName = '';
			END IF;
			RETURN indexName;
		END
$$
DELIMITER ;

-- PROCEDURE `seo`.`chongqing_tk`
DROP PROCEDURE IF EXISTS `seo`.`chongqing_tk`;
DELIMITER $$
CREATE DEFINER=`root`@`%` PROCEDURE `chongqing_tk`(
IN V_DATA_DATE VARCHAR(10)  
,IN V_ID   CHAR(19)   
)
BEGIN
	
	DECLARE V_PROC_NAME     VARCHAR(80)   DEFAULT 'seo.chongqing_tk.PRC';
    DECLARE V_START_TIME    CHAR(19)      DEFAULT NOW();
    DECLARE V_STEP_ID       INT           DEFAULT 0;
    DECLARE P_DATA_DATE     VARCHAR(10)	DEFAULT	DATE_FORMAT(V_DATA_DATE,'%Y-%m-%d');
   
     
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        GET DIAGNOSTICS CONDITION 1 @V_RETURN_CODE = RETURNED_SQLSTATE ,@V_ERROR_MSG = MESSAGE_TEXT;
        CALL ETL.EDW_PROC_ERROR_LOG(P_DATA_DATE,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,@V_RETURN_CODE,@V_ERROR_MSG);
        
        UPDATE  adm.`exec_shell_task` SET STATUS='500' WHERE id=V_ID;    
    END;
  
	SET V_DATA_DATE = DATE_FORMAT(V_DATA_DATE, '%Y-%m-%d') ;
	
	SET V_STEP_ID = 1 ;
	UPDATE 
	  adm.`exec_shell_task` 
	SET
	  STATUS = '1' 
	WHERE id=V_ID;  
	
	SET V_STEP_ID = 2 ;
	
	DELETE FROM edw.pt_tk_summary  WHERE ZWRQ = V_DATA_DATE;
	
	SET V_STEP_ID = 3 ;
	
	 	
	INSERT INTO edw.pt_tk_summary 	(
		NUUID,
		UUID,
		SQR_UUID, 	
		TRA_NO, 	
		DRAW_BACK_VOU_NO, 	
		YSPHM, 	
		ZWRQ, 	
		SQRMC,
		NSRSBH, 	
		NSRMC, 
		SQTSJE, 	
		HSZT_DM, 	
		DRAW_BACK_TRE_CODE, 	
		PAYEE_NAME, 	
		SKZH, 	
		SKYHMC, 	
		PAYEE_OP_BK_CODE, 
		TRA_AMT, 	
		TRA_AMT_MAX, 	
		YSKMDM, 	
		YSKMMC, 	
		YSFPBLDM, 	
		YSFPBLMC, 	
		ZSXMDM, 
		ZSXMMC, 	
		ZSPMDM, 	
		ZSPMMC, 	
		TDSFYYLXDM, 	
		TDSFYYLXMC, 	
		SPZT, 	
		SPJG, 	
		EXAM_ORG, 	
		EXAM_ORGMC
		)
	SELECT 
		replace(uuid(),_utf8"-",_utf8""),
		b.UUID,
		b.SQR_UUID,
		b.TRA_NO,
		b.DRAW_BACK_VOU_NO,
		e.SPHM AS YSPHM,
		a.ZWRQ,
		a.SQRMC,
		a.NSRSBH,
		a.NSRMC,
		a.SQTSJE,
		a.HSZT_DM,
		b.DRAW_BACK_TRE_CODE,
		b.PAYEE_NAME,
		a.SKZH,
		a.SKYHMC,
		b.PAYEE_OP_BK_CODE,
		b.TRA_AMT,
		b.TRA_AMT_MAX,
		c.YSKMDM,
		c.YSKMMC,
		c.YSFPBLDM,
		c.YSFPBLMC,
		c.ZSXMDM,
		c.ZSXMMC,
		c.ZSPMDM,
		c.ZSPMMC,
		c.TDSFYYLXDM,
		c.TDSFYYLXMC,
		a.SPZT,
		a.SPJG,
		b.EXAM_ORG,
		b.EXAM_ORGMC
	FROM ods.`PT_TK_SQRXX` a
  LEFT JOIN ods.`PT_TK_TKXX`  b ON a.UUID=b.SQR_UUID
  LEFT JOIN  ods.`PT_TK_TSMX` c  ON b.UUID=c.TK_UUID
  LEFT JOIN ods.PT_TK_ZSJGHSXX d ON a.UUID=d.SQR_UUID
  LEFT JOIN ods.PT_TK_SPMXXX e ON d.UUID=e.ZSJGHS_UUID
   WHERE   a.ZWRQ=V_DATA_DATE
	;
	
	SET V_STEP_ID = 4 ;
	UPDATE 
	  adm.`exec_shell_task` 
	SET
	  STATUS = '200' 
	WHERE   id=V_ID; 
    CALL ETL.EDW_PROC_TRACE_LOG(P_DATA_DATE,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
END
$$
DELIMITER ;

-- PROCEDURE `seo`.`chongqing_tk_batch`
DROP PROCEDURE IF EXISTS `seo`.`chongqing_tk_batch`;
DELIMITER $$
CREATE DEFINER=`root`@`%` PROCEDURE `chongqing_tk_batch`(
IN V_START_DATE VARCHAR(10)  
,IN V_END_DATE   VARCHAR(10) 

)
BEGIN
		
		DECLARE V_PROC_NAME     VARCHAR(80)   DEFAULT 'seo.chongqing_tk_batch.PRC';
    DECLARE V_START_TIME    CHAR(19)      DEFAULT NOW();
    DECLARE V_STEP_ID       INT           DEFAULT 0;
    DECLARE P_DATA_DATE     VARCHAR(10)	DEFAULT	DATE_FORMAT(V_START_DATE,'%Y-%m-%d');
		DECLARE V_DATA_DATE    VARCHAR(10) DEFAULT	DATE_FORMAT(V_START_DATE,'%Y-%m-%d');
   
    
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        GET DIAGNOSTICS CONDITION 1 @V_RETURN_CODE = RETURNED_SQLSTATE ,@V_ERROR_MSG = MESSAGE_TEXT;
        CALL ETL.EDW_PROC_ERROR_LOG(P_DATA_DATE,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,@V_RETURN_CODE,@V_ERROR_MSG);
    END;
		
		
	SET V_START_DATE = DATE_FORMAT(V_START_DATE, '%Y-%m-%d') ;
	SET V_END_DATE = DATE_FORMAT(V_END_DATE, '%Y-%m-%d') ;
	
	WHILE V_START_DATE<=V_END_DATE
	DO
	SET P_DATA_DATE = DATE_FORMAT(V_START_DATE, '%Y-%m-%d') ;
	SET V_DATA_DATE = DATE_FORMAT(V_START_DATE, '%Y-%m-%d') ;
		select V_DATA_DATE;
	SET V_STEP_ID = 2 ;
	
	DELETE FROM edw.pt_tk_summary  WHERE ZWRQ = V_DATA_DATE;
	
	SET V_STEP_ID = 3 ;
	
	
	INSERT INTO edw.pt_tk_summary 	(
		NUUID,
		UUID,
		SQR_UUID, 	
		TRA_NO, 	
		DRAW_BACK_VOU_NO, 	
		YSPHM, 	
		ZWRQ, 	
		SQRMC,
		NSRSBH, 	
		NSRMC, 
		SQTSJE, 	
		HSZT_DM, 	
		DRAW_BACK_TRE_CODE, 	
		PAYEE_NAME, 	
		SKZH, 	
		SKYHMC, 	
		PAYEE_OP_BK_CODE, 
		TRA_AMT, 	
		TRA_AMT_MAX, 	
		YSKMDM, 	
		YSKMMC, 	
		YSFPBLDM, 	
		YSFPBLMC, 	
		ZSXMDM, 
		ZSXMMC, 	
		ZSPMDM, 	
		ZSPMMC, 	
		TDSFYYLXDM, 	
		TDSFYYLXMC, 	
		SPZT, 	
		SPJG, 	
		EXAM_ORG, 	
		EXAM_ORGMC
		)
	SELECT 
		replace(uuid(),_utf8"-",_utf8"") as NUUID
		,t.*  from  (SELECT 
		DISTINCT
		b.UUID,
		b.SQR_UUID,
		b.TRA_NO,
		b.DRAW_BACK_VOU_NO,
		e.SPHM AS YSPHM,
		a.ZWRQ,
		a.SQRMC,
		a.NSRSBH,
		a.NSRMC,
		a.SQTSJE,
		a.HSZT_DM,
		b.DRAW_BACK_TRE_CODE,
		b.PAYEE_NAME,
		a.SKZH,
		a.SKYHMC,
		b.PAYEE_OP_BK_CODE,
		b.TRA_AMT,
		b.TRA_AMT_MAX,
		c.YSKMDM,
		c.YSKMMC,
		c.YSFPBLDM,
		c.YSFPBLMC,
		c.ZSXMDM,
		c.ZSXMMC,
		c.ZSPMDM,
		c.ZSPMMC,
		c.TDSFYYLXDM,
		c.TDSFYYLXMC,
		a.SPZT,
		a.SPJG,
		b.EXAM_ORG,
		b.EXAM_ORGMC
	FROM ods.`PT_TK_SQRXX` a
  LEFT JOIN  ods.`PT_TK_TKXX`  b ON a.UUID=b.SQR_UUID
  LEFT JOIN  ods.`PT_TK_TSMX` c  ON b.UUID=c.TK_UUID
  LEFT JOIN  ods.PT_TK_ZSJGHSXX d ON a.UUID=d.SQR_UUID
  LEFT JOIN  ods.PT_TK_SPMXXX e ON d.UUID=e.ZSJGHS_UUID
	WHERE   a.ZWRQ=V_DATA_DATE
	) t
   
	;
	
	
    CALL ETL.EDW_PROC_TRACE_LOG(P_DATA_DATE,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
	
	SET V_START_DATE = DATE_ADD(V_START_DATE,INTERVAL 1 DAY);
	
	END WHILE;
END
$$
DELIMITER ;

-- PROCEDURE `seo`.`P_VS_FIVE_PROVINCES_IN_SOUTHWEST_CHINA`
