     SELECT 
      DATE_FORMAT(V_DATA_DATE,'%Y-%m'),
  a.AREA_NO,
  a.TRECODE,
  a.TREDSCR,
  '2',
  a.SUBJECT_DSCR,
  a.INDEX_VALUE,
  a.INDEX_VALUE1,
