  LEFT JOIN stg.trs_tmis_budget_income_provinces a1 
  ON a1.DATA_DATE = DATE_FORMAT(DATE_SUB(V_DATA_DATE, INTERVAL 1 YEAR),'%Y%m')
   AND a.TRECODE = a1.TRECODE
