    GROUP BY
  a.AREA_NO,
  a.TRECODE
  ) a 
  LEFT JOIN( 
        SELECT
       DISTINCT
  DATE_FORMAT(V_DATA_DATE,'%Y-%m'),
  a.AREA_NO,
  a.TRECODE,
  a.TREDSCR,
  '2',
  a.SUBJECT_DSCR,
  ROUND(SUM(a.THIS_AMT)*100000000,4) AS INDEX_VALUE,
