SET V_STEP_ID = 2; 
INSERT INTO visual_screen.vs_growth_public_budget
SELECT 
DATE_FORMAT(v_data_date,'%Y-%m'), 
b.PID,
b.AREA_NO_ID, 
b.AREA_DSCR,
'2',
'一般公共预算收入' AS INDEX_NAME        ,  
SUM(a.THIS_AMT) 
FROM
  stg.trs_tmis_budget_income a
  LEFT JOIN 
  (SELECT
    DISTINCT p.`GUOKU_ID` AS PID,
	p.LEVEL,
