	END
$$
DELIMITER ;

-- PROCEDURE `seo`.`p_xunhuan_formula`
DROP PROCEDURE IF EXISTS `seo`.`p_xunhuan_formula`;
DELIMITER $$
CREATE DEFINER=`dis`@`%` PROCEDURE `p_xunhuan_formula`(in V_BATCH_DATE VARCHAR(10))
BEGIN
	DECLARE DONE             INT DEFAULT FALSE;	
	DECLARE V_DATA_DATE      VARCHAR(10);          
	DECLARE CUR_D_ACCT CURSOR FOR 
	select 
	distinct 
	if(
	date_format(d_acct,'%Y-%m-%d') is null,
	date_format(concat(d_acct,'01'),'%Y-%m-%d'),
	date_format(d_acct,'%Y-%m-%d')
	) as d_acct
	from 
	(
	SELECT D_ACCT 
	FROM ODS.TRS_TMIS_BUDGET_INCOME
	WHERE BATCH_DATE = V_BATCH_DATE
	UNION ALL 
	SELECT D_ACCT 
	FROM ODS.TRS_TMIS_BUDGET_PAYOUT
	WHERE BATCH_DATE = V_BATCH_DATE
	UNION ALL 
	SELECT D_ACCT 
	FROM ODS.TRS_TMIS_STOCK
	WHERE BATCH_DATE = V_BATCH_DATE) a
	order by
	if(
	date_format(d_acct,'%Y-%m-%d') is null,
	date_format(concat(d_acct,'01'),'%Y-%m-%d'),
	date_format(d_acct,'%Y-%m-%d')
	);
	
	DECLARE CUR_MONTH CURSOR FOR 
	select 
	distinct 
	if(
	date_format(d_acct,'%Y-%m-%d') is null,
	date_format(concat(d_acct,'01'),'%Y-%m'),
	date_format(d_acct,'%Y-%m')
	) as d_acct
	from 
	(
	SELECT D_ACCT 
	FROM ODS.TRS_TMIS_BUDGET_INCOME
	WHERE BATCH_DATE = V_BATCH_DATE
	UNION ALL 
	SELECT D_ACCT 
	FROM ODS.TRS_TMIS_BUDGET_PAYOUT
	WHERE BATCH_DATE = V_BATCH_DATE
	UNION ALL 
	SELECT D_ACCT 
	FROM ODS.TRS_TMIS_STOCK
	WHERE BATCH_DATE = V_BATCH_DATE) a
	order by
	if(
	date_format(d_acct,'%Y-%m-%d') is null,
	date_format(concat(d_acct,'01'),'%Y-%m-%d'),
	date_format(d_acct,'%Y-%m-%d')
	);
	
	DECLARE CONTINUE HANDLER FOR NOT FOUND SET DONE:= TRUE;
	
	
	update ods.TRS_TMIS_BUDGET_INCOME 
	set D_ACCT = case when length(D_ACCT) = 6 
				then date_format(concat(D_ACCT,'01'),'%Y-%m-%d') 
				else date_format(D_ACCT,'%Y-%m-%d') end;
	
	update ods.TRS_TMIS_BUDGET_PAYOUT 
	set D_ACCT = case when LENGTH(D_ACCT) = 6 
				then date_format(concat(D_ACCT,'01'),'%Y-%m-%d') 
				else date_format(D_ACCT,'%Y-%m-%d') end;
	
	update ods.TRS_TMIS_STOCK set TRECODE = '2200000000' ,TREDSCR = '国家金库重庆市分库' where TRECODE = 'NNNNNNNNNN';
	
	
	OPEN CUR_D_ACCT;
	ENTLOOP:LOOP
		FETCH CUR_D_ACCT INTO V_DATA_DATE;
		IF DONE THEN
		LEAVE ENTLOOP;
		END IF;
	 	
		CALL indicators_lib.p_exe_formula(V_DATA_DATE);
	        CALL edw.P_TRS_BUDGET_INCOME_COMPARE(date_format(V_DATA_DATE,'%Y%m%d'));
	        
	        IF V_DATA_DATE = LAST_DAY(V_DATA_DATE)
	        THEN 
	        CALL report.P_QUARTER_REPORT_TEXT(CONCAT(YEAR(V_DATA_DATE),'Q',QUARTER(V_DATA_DATE)));
	        CALL report.P_NEWS_FLASH_QUARTER_REPORT_TEXT(CONCAT(YEAR(V_DATA_DATE),'Q',QUARTER(V_DATA_DATE)));
	        END IF;	
	
		END LOOP ENTLOOP;
		CLOSE CUR_D_ACCT;
		SET DONE = FALSE;
	
	OPEN CUR_MONTH;
	MONTHLOOP:LOOP
		FETCH CUR_MONTH INTO V_DATA_DATE;
		IF DONE THEN
		LEAVE MONTHLOOP;
		END IF;
		
	 	
		call report.P_MONTH_REPORT_TEXT(V_DATA_DATE);
	        CALL report.P_NEWS_FLASH_MONTH_REPORT_TEXT(V_DATA_DATE);
	        CALL report.P_NEWS_FLASH_MONTH_TEXT_NUMBER(concat(V_DATA_DATE,'-01'));
	        CALL edw.P_TRS_FINANCE_TAX_STATIS(V_DATA_DATE);
	        
		END LOOP MONTHLOOP;
		CLOSE CUR_MONTH;
		SET DONE = FALSE;
	
	END
$$
DELIMITER ;

-- PROCEDURE `seo`.`p_xunhuan_formula_temp_2`
DROP PROCEDURE IF EXISTS `seo`.`p_xunhuan_formula_temp_2`;
DELIMITER $$
CREATE DEFINER=`dis`@`%` PROCEDURE `p_xunhuan_formula_temp_2`(IN START_DATE VARCHAR(10),IN END_DATE  VARCHAR(10))
BEGIN
	while START_DATE <= END_DATE
	do 
	
	
	CALL indicators_lib.p_exe_formula_hand(START_DATE,'e34ac17098ce11eab404000c298a21af');  	 		
	SET start_date = DATE_ADD(start_date,INTERVAL 1 month);
	
	
	
	
	 
	END WHILE;
	END
$$
DELIMITER ;

-- PROCEDURE `seo`.`trs_kyd_enterprise`
DROP PROCEDURE IF EXISTS `seo`.`trs_kyd_enterprise`;
DELIMITER $$
CREATE DEFINER=`dis`@`%` PROCEDURE `trs_kyd_enterprise`(IN V_DATA_DATE VARCHAR(10))
BEGIN
delete from visual_screen.trs_kyd_enterprise where DACCT = date_format(V_DATA_DATE,'%Y-%m');
insert into visual_screen.trs_kyd_enterprise
select 
	date_format(a.d_acct,'%Y-%m'),
	a.s_trecode,
	a.S_TRECODE,
	b.area_no_id,
	b.area_dscr,
	'2',
	a.ETPCODE,
	a.ETPNAME,
	sum(a.F_AMT),
	sum(DET2.F_AMT)
from edw.trs_kyd_industry a
left join EDW.trs_kyd_industry DET2
       ON DET2.D_ACCT = DATE_SUB(a.D_ACCT,INTERVAL 1 YEAR)
			AND a.S_TRECODE = DET2.S_TRECODE
		  AND a.ETPNAME = DET2.ETPNAME
		  AND a.LEV_4_ID = DET2.LEV_4_ID
			AND a.S_BDGSBTCODE = DET2.S_BDGSBTCODE
left join dmcode.cm_guoku_dimnsn b
		  ON a.S_TRECODE = b.guoku_id
where date_format(a.d_acct,'%Y-%m') between date_format(V_DATA_DATE,'%Y-01') and date_format(V_DATA_DATE,'%Y-%m')
  and a.S_BDGSBTCODE like '101%'
	and a.LEV_4_ID <> 'null'
group by
     a.S_TRECODE,
		 b.area_no_id,
		 a.ETPNAME;
COMMIT;
	END
$$
DELIMITER ;

-- PROCEDURE `seo`.`trs_kyd_enterprise_rank`
DROP PROCEDURE IF EXISTS `seo`.`trs_kyd_enterprise_rank`;
DELIMITER $$
CREATE DEFINER=`dis`@`%` PROCEDURE `trs_kyd_enterprise_rank`(IN V_DATA_DATE VARCHAR(10))
BEGIN
delete from visual_screen.trs_kyd_enterprise_rank where DACCT = date_format(V_DATA_DATE,'%Y-%m');
insert into visual_screen.trs_kyd_enterprise_rank
select 
	date_format(a.d_acct,'%Y-%m'),
	a.s_trecode,
	a.S_TRECODE,
	b.area_no_id,
	b.area_dscr,
	'2',
	case when a.LEV_1_ID in ('C','K','E','F','J') then a.LEV_1_ID
	     else 'Z' END      as index_code,
	case when a.LEV_1_ID in ('C','K','E','F','J') then a.LEV_1_DSCR
	     else '其他行业' END   as index_name,
	sum(a.F_AMT)
from edw.trs_kyd_industry a
left join dmcode.cm_guoku_dimnsn b
		  ON a.S_TRECODE = b.guoku_id
where a.d_acct like concat(date_format(V_DATA_DATE,'%Y-%m'),'%')
group by
     a.S_TRECODE,
		 b.area_no_id,
		 case when a.LEV_1_ID in ('C','K','E','F','J') then a.LEV_1_ID
	     else 'Z'  END ;
COMMIT;
	END
$$
DELIMITER ;

-- PROCEDURE `seo`.`trs_kyd_industry`
DROP PROCEDURE IF EXISTS `seo`.`trs_kyd_industry`;
DELIMITER $$
CREATE DEFINER=`dis`@`%` PROCEDURE `trs_kyd_industry`(IN V_DATA_DATE VARCHAR(10))
BEGIN
delete from visual_screen.trs_kyd_industry where DACCT = date_format(V_DATA_DATE,'%Y-%m');
insert into visual_screen.trs_kyd_industry
select 
	date_format(a.d_acct,'%Y-%m'),
	a.s_trecode,
	a.S_TRECODE,
	b.area_no_id,
	b.area_dscr,
	'2',
	a.LEV_1_ID,
	case when a.LEV_1_ID = 'C' then '汽车制造业' 
	     else a.LEV_1_DSCR end as LEV_1_DSCR,
	sum(a.F_AMT),
	sum(DET2.F_AMT)
from edw.trs_kyd_industry a
left join EDW.trs_kyd_industry DET2
       ON DET2.D_ACCT = DATE_SUB(a.D_ACCT,INTERVAL 1 YEAR)
			AND a.S_TRECODE = DET2.S_TRECODE
		  AND a.ETPNAME = DET2.ETPNAME
		  AND a.LEV_4_ID = DET2.LEV_4_ID
			AND a.S_BDGSBTCODE = DET2.S_BDGSBTCODE
left join dmcode.cm_guoku_dimnsn b
		  ON a.S_TRECODE = b.guoku_id
where a.d_acct like concat(date_format(V_DATA_DATE,'%Y-%m'),'%')
  and a.LEV_4_ID <> 'null'
  and (a.LEV_1_ID in ('K','J')
  or a.LEV_2_ID = '36')
	and a.S_BDGSBTCODE like '101%'
group by
     a.S_TRECODE,
		 b.area_no_id,
		 a.LEV_1_ID;
COMMIT;
	END
$$
DELIMITER ;

-- FUNCTION `visual_screen`.`f_get_IndexName`
DROP FUNCTION IF EXISTS `visual_screen`.`f_get_IndexName`;
DELIMITER $$
CREATE DEFINER=`root`@`%` FUNCTION `f_get_IndexName`(schemeColumns VARCHAR(1000)) RETURNS varchar(2000) CHARSET utf8
BEGIN
			DECLARE indexName VARCHAR(2000) DEFAULT '';
			
			SELECT GROUP_CONCAT(INDEX_NAME ORDER BY INSTR(schemeColumns,r.INDEX_ID)) INTO indexName FROM indicators_lib.`lib_index_relation` r WHERE INSTR(schemeColumns,r.INDEX_ID) > 0;
			IF indexName IS NULL THEN 
					SET indexName = '';
			END IF;
			RETURN indexName;
		END
$$
DELIMITER ;

-- PROCEDURE `visual_screen`.`p_abc_xunhuan`
DROP PROCEDURE IF EXISTS `visual_screen`.`p_abc_xunhuan`;
DELIMITER $$
CREATE DEFINER=`root`@`%` PROCEDURE `p_abc_xunhuan`(IN START_DATE VARCHAR(10),IN END_DATE  VARCHAR(10))
BEGIN
	while date_format(START_DATE,'%Y-%m-%d') <= date_format(END_DATE,'%Y-%m-%d')
	do 
	
			select  CONCAT(date_format(start_date,'%Y%m%d'),'大屏修改新疆跑数P_VS_REVENU_DISPLAY开始');
			
	    call visual_screen.P_VS_REVENU_DISPLAY(date_format(START_DATE,'%Y%m%d'));
			
			select  CONCAT(date_format(start_date,'%Y%m%d'),'大屏修改新疆跑数P_VS_REVENU_DISPLAY结束');
	
	
	select  CONCAT(date_format(start_date,'%Y%m%d'),'结束');
  SET start_date = DATE_ADD(date_format(start_date,'%Y-%m-%d'),INTERVAL 1 month);
        
	 
	END WHILE;
	END
$$
DELIMITER ;

-- PROCEDURE `visual_screen`.`p_exe_formula_xunhuan`
DROP PROCEDURE IF EXISTS `visual_screen`.`p_exe_formula_xunhuan`;
DELIMITER $$
CREATE DEFINER=`root`@`%` PROCEDURE `p_exe_formula_xunhuan`(IN start_date VARCHAR(10),IN end_date VARCHAR(10))
BEGIN
	WHILE start_date <= end_date
	DO 
select start_date;
CALL visual_screen.p_vs_economic_taxation                     (START_DATE);
CALL visual_screen.p_vs_growth_public_budget                  (START_DATE);
CALL visual_screen.p_vs_revenu_display                        (START_DATE);
CALL visual_screen.p_vs_amount_ranking_by_region              (START_DATE);
CALL visual_screen.p_vs_regional_taxation                     (START_DATE);
CALL visual_screen.p_vs_municipalities_directly               (START_DATE);
CALL visual_screen.p_vs_five_provinces_in_southwest_china     (START_DATE);
CALL visual_screen.p_vs_customs_revenue                       (START_DATE);
CALL visual_screen.p_vs_customs_non_tax                       (START_DATE);
CALL visual_screen.p_vs_customs_import_vat                    (START_DATE);
CALL visual_screen.p_vs_customs_import_duties                 (START_DATE);
CALL visual_screen.p_vs_import_duty_on_imported_articles      (START_DATE);
CALL visual_screen.p_vs_economic_pay                          (START_DATE);
CALL visual_screen.p_vs_region_pay                            (START_DATE);
CALL visual_screen.p_vs_subject_pay                           (START_DATE);
CALL visual_screen.p_vs_purpose_pay                           (START_DATE);
CALL visual_screen.p_vs_subject_pay_sub                       (START_DATE);
CALL visual_screen.p_vs_area_pay			      (START_DATE);
CALL visual_screen.p_vs_customs_income_situation              (START_DATE);
CALL visual_screen.P_vs_area_income              (START_DATE);
	SET start_date = DATE_ADD(start_date,INTERVAL 1 month);
	END WHILE;
	END
$$
DELIMITER ;

