  WHERE  a.DATA_DATE=DATE_FORMAT(V_DATA_DATE,'%Y%m')
  AND  a.TRECODE = '0200000000'
  AND a.SUBJECT_CODE = 'T010101'
  ) b 
  ON a.TRECODE=b.TRECODE
  UNION ALL
  SELECT
DISTINCT
  DATE_FORMAT(V_DATA_DATE,'%Y-%m'),
  a.AREA_NO,
  a.TRECODE,
  a.TREDSCR,
  '2',
  a.SUBJECT_DSCR,
  a.INDEX_VALUE	,
