  '2',
  a.SUBJECT_DSCR,
  ROUND(SUM(a.THIS_AMT)*100000000,4) AS INDEX_VALUE,
  ROUND(SUM(a1.THIS_AMT)*100000000,4) AS INDEX_VALUE1
  FROM stg.trs_tmis_budget_income_provinces a 
