        p.`GUOKU_LVL_ID_2` = c.`GUOKU_LVL_ID_1`
    OR  p.`GUOKU_LVL_ID_3` = c.`GUOKU_LVL_ID_2`
    OR  p.`GUOKU_ID` = c.`GUOKU_LVL_ID_3`
      )) b
  ON a.`TRECODE`=b.CID
