       ON b.DACCT = DATE_FORMAT(DATE_SUB(v_data_date,INTERVAL 1 YEAR),'%Y')
       AND a.GUOKU_ID = b.GUOKU_ID
       AND a.AREA_CODE = b.AREA_CODE
